const cfg = $input.first().json;
const body = (cfg.body && typeof cfg.body === 'object') ? cfg.body : {};

const defaults = {
  requestId: 'PR-' + Date.now(),
  requester: 'user@example.com',
  department: 'Field Operations',
  itemDescription: 'Ruggedized laptops for field engineers: 16GB RAM, 512GB SSD, 3-year on-site warranty',
  quantity: 100,
  budget: 140000,
  currency: 'USD',
  neededByDays: 30,
  suppliers: [
    { name: 'TechSource Global', email: 'user@example.com', country: 'US', rating: 4.6, quotedUnitPrice: 1420, leadTimeDays: 21, paymentTerms: 'Net 30', minAcceptableUnitPrice: 1250 },
    { name: 'RuggedWorks Ltd', email: 'user@example.com', country: 'DE', rating: 4.2, quotedUnitPrice: 1350, leadTimeDays: 28, paymentTerms: 'Net 45', minAcceptableUnitPrice: 1180 },
    { name: 'QuickIT Distribution', email: 'user@example.com', country: 'IN', rating: 3.8, quotedUnitPrice: 1290, leadTimeDays: 35, paymentTerms: 'Net 15', minAcceptableUnitPrice: 1120 },
    { name: 'BargainBytes', email: 'user@example.com', country: 'CN', rating: 3.1, quotedUnitPrice: 1010, leadTimeDays: 24, paymentTerms: '100% upfront', minAcceptableUnitPrice: 980 }
  ]
};

const req = { ...defaults, ...body };
if (!Array.isArray(req.suppliers) || req.suppliers.length === 0) req.suppliers = defaults.suppliers;
req.quantity = Number(req.quantity) || defaults.quantity;
req.budget = Number(req.budget) || defaults.budget;
req.neededByDays = Number(req.neededByDays) || defaults.neededByDays;

return [{
  json: {
    request: req,
    config: {
      anthropicModel: cfg.anthropicModel,
      slackChannel: cfg.slackChannel,
      autoApproveLimit: Number(cfg.autoApproveLimit),
      maxNegotiationRounds: Number(cfg.maxNegotiationRounds),
      minSupplierRating: Number(cfg.minSupplierRating),
      maxRiskScore: Number(cfg.maxRiskScore)
    }
  }
}];

const ctx = $('JS - Normalize Procurement Request').first().json;
const resp = $input.first().json;
const r = ctx.request;

const textBlock = (resp.content || []).find(b => b.type === 'text');
let plan;
try {
  plan = JSON.parse((textBlock?.text || '{}').replace(/```json|```/g, '').trim());
} catch (e) {
  plan = {};
}

const perUnitBudget = r.budget / r.quantity;
plan.targetUnitPrice = Number(plan.targetUnitPrice) > 0 ? Number(plan.targetUnitPrice) : Math.round(perUnitBudget * 0.9 * 100) / 100;
plan.walkAwayUnitPrice = Math.min(Number(plan.walkAwayUnitPrice) > 0 ? Number(plan.walkAwayUnitPrice) : perUnitBudget, perUnitBudget);
plan.mustHaveTerms = Array.isArray(plan.mustHaveTerms) ? plan.mustHaveTerms : [];
plan.negotiationLevers = Array.isArray(plan.negotiationLevers) ? plan.negotiationLevers : ['payment terms', 'lead time', 'warranty', 'volume discount'];
plan.riskFlags = Array.isArray(plan.riskFlags) ? plan.riskFlags : [];
plan.strategy = plan.strategy || 'Fallback plan: negotiate toward 90% of per-unit budget.';

return [{ json: { request: r, config: ctx.config, plan } }];

const d = $input.first().json;
const r = d.request;

return r.suppliers.map(s => ({
  json: {
    requestId: r.requestId,
    requester: r.requester,
    department: r.department,
    itemDescription: r.itemDescription,
    quantity: r.quantity,
    budget: r.budget,
    currency: r.currency,
    neededByDays: r.neededByDays,
    config: d.config,
    plan: d.plan,
    supplier: s
  }
}));

const d = $input.first().json;

return [{
  json: {
    ...d,
    round: d.round ?? 0,
    currentUnitPrice: d.currentUnitPrice ?? Number(d.supplier.quotedUnitPrice),
    history: d.history || [],
    agreed: false,
    finished: false
  }
}];

function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }
const state = ref('JS - Prepare Negotiation Round');
const resp = $input.first().json;

const round2 = n => Math.round(n * 100) / 100;
const plan = state.plan;
const maxRounds = Number(state.config.maxNegotiationRounds) || 3;
const target = Number(plan.targetUnitPrice);
const walkAwayPrice = Number(plan.walkAwayUnitPrice);
const current = Number(state.currentUnitPrice);

const textBlock = (resp.content || []).find(b => b.type === 'text');
let neg;
try {
  neg = JSON.parse((textBlock?.text || '{}').replace(/```json|```/g, '').trim());
} catch (e) {
  neg = {};
}

// Guardrail: the counter-offer must be a positive number below the current price.
let counter = Number(neg.counterUnitPrice);
if (!isFinite(counter) || counter <= 0 || counter >= current) counter = round2(current * 0.95);

// ---- SIMULATED SUPPLIER RESPONSE (replace with a real supplier portal / RFQ API / email reply) ----
const round = state.round + 1;
const floor = isFinite(Number(state.supplier.minAcceptableUnitPrice)) ? Number(state.supplier.minAcceptableUnitPrice) : current * 0.9;
const walkAway = neg.walkAway === true;

let agreed = false;
let supplierPrice = current;
let supplierResponse = '';

if (walkAway) {
  supplierResponse = 'Buyer walked away';
} else if (counter >= floor) {
  agreed = true;
  supplierPrice = counter;
  supplierResponse = 'Supplier accepted the counter-offer';
} else {
  supplierPrice = Math.max(floor, round2(current - (current - counter) * 0.4));
  supplierResponse = 'Supplier countered at ' + supplierPrice;
  if (supplierPrice <= target) agreed = true;
}

let finished = agreed || walkAway || round >= maxRounds;
// Out of rounds: accept the supplier's last price only if it is within the walk-away price.
if (finished && !agreed && !walkAway && supplierPrice <= walkAwayPrice) {
  agreed = true;
  supplierResponse += ' (accepted: within walk-away price)';
}
// ---- END SIMULATION ----

const history = [...(state.history || []), {
  round,
  ourCounter: counter,
  requestedConcessions: neg.requestedConcessions || [],
  message: neg.message || '',
  supplierPrice,
  supplierResponse
}];

return [{
  json: {
    ...state,
    round,
    currentUnitPrice: supplierPrice,
    agreed,
    finished,
    walkAway,
    finalUnitPrice: agreed ? supplierPrice : null,
    totalCost: agreed ? round2(supplierPrice * state.quantity) : null,
    history
  }
}];

function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }
const state = ref('JS - Parse Negotiation & Supplier Response');
const resp = $input.first().json;

const textBlock = (resp.content || []).find(b => b.type === 'text');
let v;
try {
  v = JSON.parse((textBlock?.text || '{}').replace(/```json|```/g, '').trim());
} catch (e) {
  v = {};
}

const issues = Array.isArray(v.issues) ? [...v.issues] : [];
const cfg = state.config;
let passed = state.agreed && v.passed !== false;

// Deterministic policy checks (these always apply, regardless of what the agent says)
if (!state.agreed) issues.push('No agreement reached with supplier');
if (state.agreed && state.totalCost > state.budget) { passed = false; issues.push('Total cost exceeds budget'); }
if (Number(state.supplier.leadTimeDays) > state.neededByDays) { passed = false; issues.push('Lead time exceeds required delivery window'); }
if (Number(state.supplier.rating) < cfg.minSupplierRating) { passed = false; issues.push('Supplier rating below minimum (' + cfg.minSupplierRating + ')'); }

const riskScore = isFinite(Number(v.riskScore)) ? Number(v.riskScore) : 50;

return [{
  json: {
    requestId: state.requestId,
    itemDescription: state.itemDescription,
    quantity: state.quantity,
    budget: state.budget,
    currency: state.currency,
    neededByDays: state.neededByDays,
    config: state.config,
    plan: state.plan,
    supplierName: state.supplier.name,
    supplierEmail: state.supplier.email,
    supplierCountry: state.supplier.country,
    supplierRating: Number(state.supplier.rating),
    leadTimeDays: Number(state.supplier.leadTimeDays),
    paymentTerms: state.supplier.paymentTerms,
    rounds: state.round,
    agreed: state.agreed,
    finalUnitPrice: state.finalUnitPrice,
    totalCost: state.totalCost,
    validationPassed: passed,
    riskScore,
    issues,
    recommendation: v.recommendation || '',
    history: state.history
  }
}];

function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }
// The Postgres node replaces the item with the query result, so put the full offer back
// before returning to the loop. Loop Over Suppliers then collects every offer on its "done" output.
const offer = ref('JS - Parse Validation');
return [{ json: offer }];

const offers = $input.all().map(i => i.json).filter(o => o && o.requestId);
const ctx = offers[0];
const round2 = n => Math.round(n * 100) / 100;

const eligible = offers.filter(o => o.agreed && o.validationPassed);
const rejected = offers.filter(o => !(o.agreed && o.validationPassed));

const norm = (v, min, max, invert) => max === min ? 1 : (invert ? (max - v) / (max - min) : (v - min) / (max - min));
const prices = eligible.map(o => o.finalUnitPrice);
const leads = eligible.map(o => o.leadTimeDays);
const pMin = Math.min(...prices), pMax = Math.max(...prices);
const lMin = Math.min(...leads), lMax = Math.max(...leads);

const ranked = eligible.map(o => {
  const score = 0.5 * norm(o.finalUnitPrice, pMin, pMax, true)
    + 0.2 * norm(o.leadTimeDays, lMin, lMax, true)
    + 0.2 * (o.supplierRating / 5)
    + 0.1 * (1 - o.riskScore / 100);
  return {
    supplierName: o.supplierName,
    supplierEmail: o.supplierEmail,
    finalUnitPrice: o.finalUnitPrice,
    totalCost: o.totalCost,
    leadTimeDays: o.leadTimeDays,
    paymentTerms: o.paymentTerms,
    supplierRating: o.supplierRating,
    riskScore: o.riskScore,
    issues: o.issues,
    score: round2(score)
  };
}).sort((a, b) => b.score - a.score);

const rejectedSummary = rejected.map(o => ({ supplierName: o.supplierName, reasons: o.issues }));

return [{
  json: {
    requestId: ctx.requestId,
    itemDescription: ctx.itemDescription,
    quantity: ctx.quantity,
    budget: ctx.budget,
    currency: ctx.currency,
    config: ctx.config,
    plan: ctx.plan,
    totalOffers: offers.length,
    eligibleCount: eligible.length,
    ranked,
    rejectedSummary
  }
}];

const ctx = $('JS - Rank Offers').first().json;
const resp = $input.first().json;

const textBlock = (resp.content || []).find(b => b.type === 'text');
let ai;
try {
  ai = JSON.parse((textBlock?.text || '{}').replace(/```json|```/g, '').trim());
} catch (e) {
  ai = {};
}

const notes = [];
let route = ['auto_approve', 'escalate', 'reject'].includes(ai.decision) ? ai.decision : 'escalate';
if (route === 'escalate' && !ai.decision) notes.push('Approval agent output unreadable: defaulted to human escalation');

const ranked = ctx.ranked || [];
const chosen = ranked.find(o => o.supplierName === ai.recommendedSupplier) || ranked[0] || null;
const cfg = ctx.config;

if (!chosen) {
  route = 'reject';
  notes.push('No eligible offers (agreed and validated)');
} else {
  if (route === 'auto_approve') {
    if (chosen.totalCost > cfg.autoApproveLimit) { route = 'escalate'; notes.push('Guardrail: total exceeds auto-approve limit'); }
    if (chosen.riskScore > cfg.maxRiskScore) { route = 'escalate'; notes.push('Guardrail: risk score exceeds maximum'); }
  }
  if (chosen.totalCost > ctx.budget && route !== 'reject') { route = 'escalate'; notes.push('Guardrail: total exceeds budget'); }
}

return [{
  json: {
    requestId: ctx.requestId,
    itemDescription: ctx.itemDescription,
    quantity: ctx.quantity,
    budget: ctx.budget,
    currency: ctx.currency,
    config: cfg,
    route,
    chosenOffer: chosen,
    rationale: ai.rationale || (chosen ? 'Top ranked offer selected' : 'No eligible offers'),
    conditions: Array.isArray(ai.conditions) ? ai.conditions : [],
    guardrailNotes: notes,
    eligibleCount: ctx.eligibleCount,
    totalOffers: ctx.totalOffers
  }
}];

